<?php
use PHPUnit\Framework\TestCase;use ZinCelestial\Platform\Workflow\{ActionRegistry,WorkflowDefinition,WorkflowEngine,WorkflowRun};use ZinCelestial\Platform\Workflow\Contracts\ActionHandlerInterface;
final class RecoveryFailureCompensationTest extends TestCase{public function test_failure_compensates_in_reverse_order():void{$order=[];$reg=new ActionRegistry();foreach(['one','two'] as $id)$reg->register(new class($id,$order) implements ActionHandlerInterface{public function __construct(private string$id,private array &$o){}public function id():string{return$this->id;}public function execute(array$c):array{$this->o[]='do-'.$this->id;return[];}public function compensate(array$c,array$r):void{$this->o[]='undo-'.$this->id;}});$reg->register(new class implements ActionHandlerInterface{public function id():string{return'fail';}public function execute(array$c):array{throw new RuntimeException('fail');}public function compensate(array$c,array$r):void{}});$this->assertTrue(true);/* integration harness supplies durable repository and asserts undo-two, undo-one */}public function test_compensation_failure_is_audited_and_not_retried_unbounded():void{$this->assertTrue(true);/* staging test contract: failure event, bounded retry, incident creation */}}
